use codeint_model::language::SourceSet;

const TEST_FOLDERS: [&str; 5] = ["__tests__", "test", "tests", "test-dts", "type-tests"];
const TEST_FILE_MARKERS: [&str; 4] = ["test", "spec", "test-d", "spec-d"];
const GENERATED_MARKERS: [&str; 7] = [
    "@generated",
    "autogenerated",
    "auto-generated",
    "auto generated",
    "automatically generated",
    "generated by",
    "do not edit",
];

pub(crate) fn source_set<'text>(
    path: &str,
    mut header_comments: impl Iterator<Item = &'text str>,
) -> SourceSet {
    let (folders, file_name) = path.rsplit_once('/').unwrap_or(("", path));
    let in_test_folder = folders
        .split('/')
        .any(|folder| TEST_FOLDERS.contains(&folder));
    if header_comments.any(has_generated_marker) {
        SourceSet::Generated
    } else if in_test_folder || is_test_file_name(file_name) {
        SourceSet::Test
    } else {
        SourceSet::Production
    }
}

fn is_test_file_name(file_name: &str) -> bool {
    let Some((without_extension, _extension)) = file_name.rsplit_once('.') else {
        return false;
    };
    let Some((stem, marker)) = without_extension.rsplit_once('.') else {
        return false;
    };
    !stem.is_empty() && TEST_FILE_MARKERS.contains(&marker)
}

fn has_generated_marker(comment: &str) -> bool {
    let comment = comment.to_lowercase();
    GENERATED_MARKERS
        .iter()
        .any(|marker| comment.contains(marker))
}
